import pytest
from markupsafe import Markup, escape_silent
@pytest.mark.parametrize('value,expected', [(None,''),('',''),('<b>','&lt;b&gt;'),('a&b','a&amp;b'),(False,'False'),(0,'0'),('中文','中文')])
def test_values(value,expected):
    result = escape_silent(value)
    assert isinstance(result,Markup)
    assert str(result)==expected
def test_html_protocol_preserved():
    class HasHTML:
        def __html__(self):
            return '<strong>safe</strong>'
    assert escape_silent(HasHTML()) == Markup('<strong>safe</strong>')
def test_safe_markup_not_double_escaped():
    assert escape_silent(Markup('<b>safe</b>')) == Markup('<b>safe</b>')
